def escape_path(path: str) -> str:
    """Escape characters that could be split or quoted by a shell/xargs."""
    out = []
    for char in path:
        if char.isspace() or char in "'\"\\":
            out.append("\\")
        out.append(char)
    return "".join(out)


def printx(path: str) -> str:
    """Return one -printx record, including its newline."""
    return escape_path(path) + "\n"
